mapper.select:
SELECT

underlying_code AS underlyingCode,
SUM(realized_pnl) AS pnl,
COUNT(*) AS cnt


FROM obt_close_record


WHERE task_id = #{taskId}


     AND close_date >= #{startDate} 


     AND close_date <= #{endDate} 


GROUP BY underlying_code

ORDER BY pnl DESC

SELECT AVG(hold_days)
FROM obt_close_record
WHERE task_id = #{taskId}
